-- kto100-2025: 100곳 (tools/kto100/make-sql.mts가 만듦, 여러 번 돌려도 같음)
begin;
on conflict (list, name) do update set no = excluded.no,
  content_id = coalesce(excluded.content_id, curated_places.content_id),
  -- 서버에서 TourAPI로 채운 좌표(content_id 있음)는 근사값으로 되돌리지 않는다
  lat = case when excluded.content_id is null and curated_places.content_id is not null then curated_places.lat else excluded.lat end,
  lng = case when excluded.content_id is null and curated_places.content_id is not null then curated_places.lng else excluded.lng end,
  addr = case when excluded.content_id is null and curated_places.content_id is not null then curated_places.addr else excluded.addr end,
  area = excluded.area, region = excluded.region, image = coalesce(excluded.image, curated_places.image),
  our_place_id = coalesce(excluded.our_place_id, curated_places.our_place_id), updated_at = now();
delete from curated_places where list = 'kto100-2025' and name not in ('5대 고궁', 'N서울타워', '광화문광장&청계광장', '국립중앙박물관', '서울스카이&롯데월드&석촌호수', '성수동 거리&서울숲', '청와대 앞길&서촌마을', '한강공원', '홍대 레드로드(홍대문화예술관광특구)', '개항장문화지구-인천차이나타운(송월동 동화마을)', '교동도', '송도 센트럴파크', '아침고요수목원', '서울대공원(서울랜드)&국립현대미술관 과천&국립과천과학관', '광명동굴', '수원화성', '두물머리', '한국민속촌', '에버랜드&캐리비안베이', '임진각&파주 DMZ', '헤이리 예술마을', '제부도&제부도해상케이블카', '정동심곡 바다부채길', '도째비골 스카이밸리&해랑전망대', '무릉계곡&무릉별유천지', '설악산국립공원', '속초관광수산시장', '뮤지엄산&간현관광지(소금산 그랜드밸리)', '원대리 자작나무숲', '철원 한탄강 주상절리길(잔도)', '남이섬', '대관령', '발왕산(천년주목숲길)', '장태산자연휴양림', '국립세종수목원', '도담삼봉', '만천하스카이워크&단양강 잔도', '보은 법주사&속리산테마파크', '청풍호', '청남대', '공주 백제유적지(공산성, 공주 무령왕릉과 왕릉원)', '대천해수욕장', '부여 백제유적지(궁남지, 부소산성)', '서산 해미읍성', '현충사', '예당관광지(예당호 출렁다리&음악분수, 예당호 모노레일)', '독립기념관', '꽃지해수욕장', '국립아시아문화전당', '무등산국립공원', '남원관광단지&광한루원', '반디랜드&태권도원', '변산반도국립공원', '강천산군립공원', '오성한옥마을', '전주한옥마을', '내장산국립공원', '마이산도립공원', '섬진강기차마을', '광양 매화마을&청매실농원', '죽녹원&관방제림', '목포근대역사문화공간&목포해상케이블카', '순천만국가정원&순천만습지', '퍼플섬', '엑스포해양공원', '정남진 편백숲 우드랜드', '감천문화마을', '광안리해변&SUP존', '부산엑스더스카이&그린레일웨이', '태종대유원지', '해동용궁사&오시리아관광단지', '해운대&송정해수욕장', '사유원', '서문시장&동성로', '팔공산국립공원', '대왕암공원', '영남알프스(간월재)', '태화강국가정원', '경주대릉원(동궁과 월지, 첨성대&황리단길&월정교)', '불국사&석굴암', '국립백두대간수목원', '안동하회마을', '울릉도&독도', '주왕산국립공원&주산지', '스페이스워크', '거제식물원', '독일마을', '사천바다케이블카&아라마루 아쿠아리움', '동의보감촌', '통도사', '진주성', '우포늪', '디피랑', '하동 쌍계사&화개장터', '머체왓숲길', '비자림', '성산일출봉', '우도', '제주올레길', '한라산국립공원');
commit;
